    // @VisibleForTesting — Portal/Test-Eingang: isolierte Überschreibung pro Sprache.
    // Im Produktionspfad niemals belegt; in Tests via ManualScreenshotTest gesetzt.
    private val _injectedLanguages = mutableMapOf<String, Map<String, String>>()

    @androidx.annotation.VisibleForTesting
    fun injectLanguage(langCode: String, strings: Map<String, String>) {
        _injectedLanguages[langCode] = strings
    }

    @androidx.annotation.VisibleForTesting
    fun clearInjectedLanguage(langCode: String) {
        _injectedLanguages.remove(langCode)
    }

    // Z-2/Z-4: geladene Sprachpakete (Portal-Stand). Fuer de/en beim Start aus den
    // eingecheckten Assets `assets/l10n/de.json`/`en.json` befuellt (loadBundledAssets),
    // fuer nachgeladene Sprachen aus dem LocalePackStore (Z-3, SettingsViewModel).
    private val packs = mutableMapOf<String, Map<String, String>>()

    // Z-4: eigenstaendiges Asset-EN, unabhaengig vom Paket der gewaehlten Sprache — das
    // zweite Kettenglied (E-P4), gilt auch wenn packs[lang] fehlt oder unvollstaendig ist.
    @Volatile
    private var bundleEn: Map<String, String> = emptyMap()

    @androidx.annotation.VisibleForTesting
    fun injectPack(code: String, strings: Map<String, String>) {
        packs[code] = strings
    }

    @androidx.annotation.VisibleForTesting
    fun clearPack(code: String) {
        packs.remove(code)
    }

    @androidx.annotation.VisibleForTesting
    fun injectBundleEn(strings: Map<String, String>) {
        bundleEn = strings
    }

    @androidx.annotation.VisibleForTesting
    fun resetBundleEn() {
        bundleEn = emptyMap()
    }

    /**
     * Z-2: Paket de/en aus den eingecheckten Assets laden (Hauptfaden, synchron — Assets
     * 17.732 + 16.661 Bytes (Stand `24a18ee`, `wc -c`), Zeit gemessen in
     * `L10nBundleLoadTimeTest`, H-5). Bei fehlendem/kaputtem Asset bleibt die
     * bestehende Map-Kette (Z-4, vierte/fuenfte Stufe) der Rueckfall — kein Absturz.
     */
    fun loadBundledAssets(context: Context) {
        listOf("de", "en").forEach { code ->
            try {
                val text = context.assets.open("l10n/$code.json").bufferedReader(Charsets.UTF_8).use { it.readText() }
                val obj = org.json.JSONObject(text)
                val map = mutableMapOf<String, String>()
                obj.keys().forEach { k -> map[k] = obj.getString(k) }
                packs[code] = map
                if (code == "en") bundleEn = map
            } catch (e: Exception) {
                // Asset fehlt oder ist kaputt: Kette faellt auf translations[...] zurueck (Z-4).
            }
        }
    }

    private val translations: Map<String, Map<String, String>> by lazy {
        mapOf(
            "de" to deTranslations(),
            "no" to noTranslations(),
            "en" to enTranslations(),
            "it" to itTranslations(),
            "nl" to nlTranslations(),
            "fr" to frTranslations(),
            "es" to esTranslations(),
            "pt" to ptTranslations(),
            "pl" to plTranslations(),
            "cs" to csTranslations(),
            "sk" to skTranslations(),
            "sl" to slTranslations(),
            "hr" to hrTranslations(),
            "hu" to huTranslations(),
            "ro" to roTranslations(),
            "bg" to bgTranslations(),
            "el" to elTranslations(),
            "da" to daTranslations(),
            "sv" to svTranslations(),
            "fi" to fiTranslations(),
            "et" to etTranslations(),
            "lv" to lvTranslations(),
            "lt" to ltTranslations(),
            "ga" to gaTranslations(),
            "mt" to mtTranslations(),
            "ar" to arTranslations(),
            "ru" to ruTranslations(),
            "tr" to trTranslations(),
            "sr" to srTranslations(),
            "sq" to sqTranslations(),
            "zh" to zhTranslations(),
            "ja" to jaTranslations(),
            "ko" to koTranslations(),
            "id" to idTranslations(),
            "th" to thTranslations(),
        )
    }

    fun init(context: Context, refreshPortal: Boolean = true) {
        // Z-2: Assets synchron auf dem Hauptfaden laden (17.732 + 16.661 Bytes, Stand
        // `24a18ee`, `wc -c`; Zeit gemessen in L10nBundleLoadTimeTest, H-5) -- die Kette
        // funktioniert auch ohne Paket (Z-4-Stufen).
        loadBundledAssets(context)
        // N-1 (Runde 2, B-1): einmal geladene Pakete beim Start wieder einhaengen -- nur aus
        // dem Dateisystem, nie auf eine Portalantwort wartend (Flugmodus-fest).
        restoreStoredPacks(context)
        // N-1 (Runde 2, B-1): das Lesen der gespeicherten Sprache bleibt im IO-Faden — der
        // Hauptfaden wird NICHT blockiert (Welle 28 entfernte Anzeigefaden-Zugriffe wegen
        // Einfrierverdacht im Feldlauf; runBlocking hier war ein Rueckbau). Bis die Sprache
        // steht, haelt MainActivity den System-Splash zurueck (setKeepOnScreenCondition,
        // Weg (a) des Pruefers): C-2/Z-3 bleibt erfuellt, das erste Bild erscheint nie vor
        // der gespeicherten Sprache.
        _languageSettled.value = false
        CoroutineScope(Dispatchers.IO).launch {
            _currentLanguage.value = readStoredLanguage(context)
            _languageSettled.value = true
            if (refreshPortal) refreshAvailableLanguages(context)
        }
    }

    /**
     * Z-5: gespeicherte Sprache bleibt gewaehlt, auch wenn sie (noch) nicht in der
     * sichtbaren Liste steht -- die getString-Kette liefert dann EN statt eines
     * stillen Sprungs auf "de" (AUFTRAG.md Abschnitt 1, Punkt 4; Z-5 ersetzt das
     * fruehere BETA-Gate-Verhalten "unbekannt -> de").
     *
     * C-2 (Z-3), N-1 (Runde 2, Befund B-1): laeuft auf dem IO-Faden, nicht mehr
     * blockierend im Startpfad -- der erste Lesevorgang ist am Entwicklungsrechner
     * mit 129,04/151,00 ms gemessen (PRUEFBERICHT_A, SONDE-C), ueber H-5 (50 ms).
     * Der System-Splash wird stattdessen zurueckgehalten, bis [languageSettled]
     * steht. Der Gurtel [START_LANGUAGE_READ_TIMEOUT_MS] begrenzt ein blockierendes
     * Speichermedium: nach Ablauf faellt die App auf "de" zurueck und zeichnet.
     * Messungen in `LocalizationManagerStartLanguageTest` (erster Lesevorgang und
     * warme Wiederholung, je mit Bezeichnung).
     */
    internal suspend fun readStoredLanguage(context: Context): String = try {
        withTimeout(START_LANGUAGE_READ_TIMEOUT_MS) {
            langStoreFor(context).data.first()[KEY_LANGUAGE]
        } ?: "de"
    } catch (e: kotlinx.coroutines.TimeoutCancellationException) {
        // Gurtel gerissen: Speicher haengt. Fallback "de" statt ewigem Startbildschirm (N-1).
        "de"
    } catch (e: Exception) {
        // Unlesbarer Speicher: wie kein Eintrag behandeln -- der Start darf nicht scheitern.
        "de"
    }

    /**
     * N-1: alle im LocalePackStore abgelegten Pakete (auch nach Neustart) in die Kette
     * haengen. Ein kaputtes Paket wird uebersprungen, die Kette faellt dann auf Paket-EN/Map.
     */
    fun restoreStoredPacks(context: Context) {
        val store = LocalePackStore(context)
        store.listLoaded().filter { it != "de" && it != "en" }.forEach { code ->
            try {
                store.load(code)?.let { packs[code] = it }
            } catch (e: Exception) {
                // unlesbares Paket: nicht einhaengen, Kette liefert weiter (Z-4)
            }
        }
    }

    /** Z-3: ein nachgeladenes Sprachpaket in die Kette einhaengen (erstes Kettenglied). */
    fun loadPack(code: String, values: Map<String, String>) {
        packs[code] = values
    }

    /** Z-3: ein Sprachpaket wieder entfernen. de/en (Assets, immer BUNDLED) bleiben stehen. */
    fun unloadPack(code: String) {
        if (code != "de" && code != "en") packs.remove(code)
    }

    /**
     * Z-5: Sprachliste ausschliesslich vom Portal (R-1, PLAN_NACHTRAG). Bei Nichterreichbarkeit
     * die zuletzt gespeicherte Liste, sonst das Paket (de/en). Die 33 uebrigen Map-Sprachen
     * werden NICHT angeboten, solange das Portal sie nicht fuehrt.
     */
    fun refreshAvailableLanguages(context: Context) {
        val store = LocalePackStore(context)
        val loadedCodes = (packs.keys + store.listLoaded()).toSet()
        val result = L10nPortalClient().fetchLocales()
        _availableLanguages.value = when (result) {
            is LocalesResult.Ok -> {
                store.saveLocalesList(result.locales.map { it.code })
                computeAvailableLanguages(result.locales, null, loadedCodes)
            }
            is LocalesResult.Unavailable -> {
                computeAvailableLanguages(null, store.loadLocalesList(), loadedCodes)
            }
        }
    }

    fun setLanguage(context: Context, langCode: String) {
        _currentLanguage.value = langCode
        CoroutineScope(Dispatchers.IO).launch {
            langStoreFor(context).edit { it[KEY_LANGUAGE] = langCode }
        }
    }

    /**
     * Nur fuer Tests (C-2, Z-3, Volllauf-Fund 19.09.2026): Umleitung aller langStore-Zugriffe
     * auf eine vom Test erzeugte frische Instanz. Grund: der Prozess-Singleton
     * `Context.langStore` bindet sich beim ersten Zugriff an die erste Sandbox, und auf dieser
     * Maschine scheitert unter Robolectric JEDES zweite Schreiben auf dieselbe DataStore-Datei
     * (belege/h1_platform_sonde.txt). Im isolierten Klassenlauf war der Seed das erste und
     * einzige Schreiben -- im Volllauf schlugen die Laeufe vorher zu. Der Test erzeugt deshalb
     * je Test eine frische Instanz mit frischer Datei (Muster: Test-Konstruktor von
     * `DamagePresetRepository`). In der Produktion bleibt die Umleitung leer.
     *
     * N-7 (Runde 2, Befund B-7): das Feld ist nicht mehr oeffentlich veraenderlich --
     * gesetzt wird es ausschliesslich ueber [setLanguageStoreOverrideForTest]. Der globale
     * Schalter als Bauform bleibt (eine Strukturaenderung waere Rueckfrage R-1 gewesen);
     * die Naht ist jetzt privat und nur ueber die benannte Test-Schnittstelle erreichbar.
     */
    private var languageStoreOverrideForTest: DataStore<Preferences>? = null

    @androidx.annotation.VisibleForTesting
    fun setLanguageStoreOverrideForTest(store: DataStore<Preferences>?) {
        languageStoreOverrideForTest = store
    }

    private fun langStoreFor(context: Context): DataStore<Preferences> =
        languageStoreOverrideForTest ?: context.langStore

    /**
     * Nur fuer Tests (C-2, Z-3): schreibt die gespeicherte Sprache direkt in den langStore,
     * ohne den Flow anzufassen -- stellt den Zustand "Fremdsprache gewaehlt, Prozess beendet"
     * her. Existiert am Ausgangskopf nicht; eigene Zeile im Rot-zuerst-Nachweis (PLAN 4.3).
     * Schreiben laeuft ueber [langStoreFor]: mit gesetzter Umleitung in die frische Testdatei.
     */
    @androidx.annotation.VisibleForTesting
    suspend fun seedStoredLanguageForTest(context: Context, code: String) {
        langStoreFor(context).edit { it[KEY_LANGUAGE] = code }
    }

    /**
     * Nur fuer Tests (C-2, Z-3): Flow auf "de" zurueck, Speicher unberuehrt -- der Zustand
     * eines frischen Prozesses, dessen erste Zeile der gespeicherten Sprache noch aussteht.
     * N-1 (Runde 2): setzt auch `languageSettled` zurueck -- ein frischer Prozess hat die
     * Sprache nicht gelesen, der Splash haelt.
     */
    @androidx.annotation.VisibleForTesting
    fun resetInMemoryLanguageForTest() {
        _currentLanguage.value = "de"
        _languageSettled.value = false
    }

    // Z-6/RB-5 (BundleGapTest): Schluesselmengen der de/en-Map-Bloecke, nur fuer den Test.
    @androidx.annotation.VisibleForTesting
    fun deMapKeysForTest(): Set<String> = deTranslations().keys

    @androidx.annotation.VisibleForTesting
    fun enMapKeysForTest(): Set<String> = enTranslations().keys

    /**
     * Z-8: alle bekannten Werte eines Schluessels ueber alle Sprachen (Map-Bloecke + Pakete)
     * hinweg -- fuer `DamagePresetRepository`, um einen v1-Altbestand (Text statt Schluessel)
     * gegen die Standardbezeichnungen zurueckzuerkennen (Migration).
     */
    fun allValuesForKey(key: String): Set<String> {
        val values = mutableSetOf<String>()
        translations.values.forEach { block -> block[key]?.let { values.add(it) } }
        packs.values.forEach { pack -> pack[key]?.let { values.add(it) } }
        bundleEn[key]?.let { values.add(it) }
        return values
    }

    fun getString(key: String): String = getString(key, _currentLanguage.value)

    /**
     * Z-4/E-P4: Kette pack[lang] -> Asset-EN (bundleEn) -> Map[lang] -> Map[en] -> Schluessel.
     * Deutsch ist ab dieser Welle kein eigenes Rueckfallglied mehr (AUFTRAG.md Abschnitt 1,
     * Punkt 4) -- die bestehende Map bleibt Uebergang (E-4), aber ihr Deutsch-Block wird fuer
     * `langCode != "de"` nie gelesen. Z-6: jeder Uebergang auf Englisch bzw. auf den
     * Schluesselnamen wird gezaehlt (FallbackCounter), ausser wenn die gewaehlte Sprache
     * selbst schon Englisch ist.
     */
    fun getString(key: String, langCode: String): String {
        packs[langCode]?.get(key)?.let { return it }

        if (langCode != "en") {
            bundleEn[key]?.let {
                FallbackCounter.recordToEnglish(key)
                return it
            }
        }

        val fromMapLang = _injectedLanguages[langCode]?.get(key) ?: translations[langCode]?.get(key)
        if (fromMapLang != null) return fromMapLang

        val fromMapEn = _injectedLanguages["en"]?.get(key) ?: translations["en"]?.get(key)
        if (fromMapEn != null) {
            if (langCode != "en") FallbackCounter.recordToEnglish(key)
            return fromMapEn
        }

        FallbackCounter.recordToKeyName(key)
        return key
    }
}

/**
 * Composable-friendly string lookup. Recomposes when language changes.
 */
@Composable
fun S(key: String): String {
    // Den State-Wert WIRKLICH lesen und für den Lookup verwenden: Compose invalidiert nur
    // Kompositionen, die den Snapshot-State gelesen haben — ein nie gelesenes `lang`
    // abonniert den Sprachwechsel nicht zuverlässig.
    val lang by LocalizationManager.currentLanguage.collectAsState()
    return LocalizationManager.getString(key, lang)
}

